import 'package:camera/camera.dart';
import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import '../services/oil_color_service.dart';
import '../theme/app_theme.dart';

Future<void> openOilCheck(BuildContext context) => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const OilCheckScreen()));
class OilCheckScreen extends StatefulWidget { const OilCheckScreen({super.key}); @override State<OilCheckScreen> createState()=>_OilCheckScreenState(); }
class _OilCheckScreenState extends State<OilCheckScreen> { CameraController? camera; OilColorResult? result; bool analyzing=false; String? error;
 @override void initState(){super.initState();_start();} Future<void> _start()async{try{final cams=await availableCameras();camera=CameraController(cams.first,ResolutionPreset.high,enableAudio:false);await camera!.initialize();if(mounted)setState((){});}catch(_){if(mounted)setState(()=>error='No pudimos abrir la cámara.');}}
 Future<void> _capture()async{if(camera==null||analyzing)return;setState(()=>analyzing=true);try{final image=await camera!.takePicture();final value=await OilColorService().analyze(image.path);if(mounted)setState(()=>result=value);}finally{if(mounted)setState(()=>analyzing=false);}}
 @override void dispose(){camera?.dispose();super.dispose();} @override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.black,body:Stack(fit:StackFit.expand,children:[if(camera?.value.isInitialized==true)CameraPreview(camera!)else Center(child:error==null?const CircularProgressIndicator(color:AppTheme.teal):Text(error!,style:const TextStyle(color:Colors.white))),const DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Color(0x99000000),Colors.transparent,Color(0xCC000000)]))),SafeArea(child:Padding(padding:const EdgeInsets.all(22),child:Column(children:[Row(children:[IconButton.filledTonal(onPressed:()=>Navigator.pop(context),icon:const Icon(CupertinoIcons.xmark),style:IconButton.styleFrom(backgroundColor:Colors.black45,foregroundColor:Colors.white)),const SizedBox(width:10),const Text('PRUEBA DE ACEITE',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800,letterSpacing:1))]),const Spacer(),const _DipstickGuide(),const SizedBox(height:20),Text(result?.title??'Enfoca la zona húmeda de la varilla',style:const TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w800),textAlign:TextAlign.center),const SizedBox(height:8),Text(result?.guidance??'Limpia la varilla, vuelve a insertarla y retírala. Usa luz natural.',style:const TextStyle(color:Colors.white70),textAlign:TextAlign.center),const SizedBox(height:22),if(result!=null)_ResultCard(result:result!),FilledButton.icon(onPressed:analyzing?null:_capture,style:FilledButton.styleFrom(backgroundColor:AppTheme.teal,minimumSize:const Size.fromHeight(54)),icon:analyzing?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(CupertinoIcons.camera_fill),label:Text(analyzing?'Analizando...':'Analizar color de aceite'))])))])); }
class _DipstickGuide extends StatelessWidget { const _DipstickGuide(); @override Widget build(BuildContext context)=>Container(width:260,height:160,decoration:BoxDecoration(border:Border.all(color:const Color(0xFF66F0E4),width:3),borderRadius:BorderRadius.circular(28)),child:const Center(child:Icon(CupertinoIcons.line_horizontal_3_decrease_circle,color:Color(0xFF66F0E4),size:60))); }
class _ResultCard extends StatelessWidget { const _ResultCard({required this.result}); final OilColorResult result; @override Widget build(BuildContext context){final dark=result.appearance==OilAppearance.dark;return Container(width:double.infinity,margin:const EdgeInsets.only(bottom:14),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xEFFFFFFF),borderRadius:BorderRadius.circular(22)),child:Row(children:[Icon(dark?CupertinoIcons.exclamationmark_triangle_fill:CupertinoIcons.check_mark_circled_solid,color:dark?Colors.deepOrange:Colors.green),const SizedBox(width:12),Expanded(child:Text(result.guidance,style:const TextStyle(fontWeight:FontWeight.w600)))]));}}
